pragma solidity 0.8.20;

// ============ External Imports ============
import { IFoundationMarket } from "../vendor/markets/IFoundationMarket.sol";

// ============ Internal Imports ============
import { IMarketWrapper } from "./IMarketWrapper.sol";

/**
 * @title FoundationMarketWrapper
 * @author Anna Carroll
 * @notice MarketWrapper contract implementing IMarketWrapper interface
 * according to the logic of Foundation's NFT Market
 * Original Foundation NFT Market code: https://etherscan.io/address/0xa7d94560dbd814af316dd96fde78b9136a977d1c#code
 */
contract FoundationMarketWrapper is IMarketWrapper {
    // ============ Internal Immutables ============

    IFoundationMarket internal immutable market;

    // ======== Constructor =========

    constructor(address _foundationMarket) {
        market = IFoundationMarket(_foundationMarket);
    }

    // ======== External Functions =========

    /**
     * @notice Determine whether there is an existing auction
     * for this token on the market
     * @return TRUE if the auction exists
     */
    function auctionExists(uint256 auctionId) public view returns (bool) {
        // line 219 of NFTMarketReserveAuction, logic within placeBid() function (not exposed publicly)
        IFoundationMarket.ReserveAuction memory _auction = market.getReserveAuction(auctionId);
        return _auction.amount != 0;
    }

    /**
     * @notice Determine whether the given auctionId is
     * an auction for the tokenId + nftContract
     * @return TRUE if the auctionId matches the tokenId + nftContract
     */
    function auctionIdMatchesToken(
        uint256 auctionId,
        address nftContract,
        uint256 tokenId
    ) public view override returns (bool) {
        return auctionId == market.getReserveAuctionIdFor(nftContract, tokenId);
    }

    /**
     * @notice Query the current highest bidder for this auction
     * @return highest bidder
     */
    function getCurrentHighestBidder(uint256 auctionId) external view override returns (address) {
        // line 279 of NFTMarketReserveAuction, getMinBidAmount() function
        IFoundationMarket.ReserveAuction memory _auction = market.getReserveAuction(auctionId);
        return _auction.bidder;
    }

    /**
     * @notice Calculate the minimum next bid for this auction
     * @return minimum bid amount
     */
    function getMinimumBid(uint256 auctionId) external view override returns (uint256) {
        // line 279 of NFTMarketReserveAuction, getMinBidAmount() function
        return market.getMinBidAmount(auctionId);
    }

    /**
     * @notice Submit bid to Market contract
     */
    function bid(uint256 auctionId, uint256 bidAmount) external override {
        // line 217 of NFTMarketReserveAuction, placeBid() function
        (bool success, bytes memory returnData) = address(market).call{ value: bidAmount }(
            abi.encodeWithSignature("placeBid(uint256)", auctionId)
        );
        require(success, string(returnData));
    }

    /**
     * @notice Determine whether the auction has been finalized
     * @return TRUE if the auction has been finalized
     */
    function isFinalized(uint256 auctionId) external view override returns (bool) {
        // line 266 of NFTMarketReserveAuction,
        // the auction is deleted at the end of the finalizeReserveAuction() function
        // since we checked that the auction DID exist when we deployed the partyBid,
        // if it no longer exists that means the auction has been finalized.
        return !auctionExists(auctionId);
    }

    /**
     * @notice Finalize the results of the auction
     */
    function finalize(uint256 auctionId) external override {
        // line 260 of finalizeReserveAuction, finalizeReserveAuction() function
        // will revert if auction has not started or still in progress
        market.finalizeReserveAuction(auctionId);
    }
}
"},"contracts/market-wrapper/IMarketWrapper.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.20;

/**
 * @title IMarketWrapper
 * @author Anna Carroll
 * @notice IMarketWrapper provides a common interface for
 * interacting with NFT auction markets.
 * Contracts can abstract their interactions with
 * different NFT markets using IMarketWrapper.
 * NFT markets can become compatible with any contract
 * using IMarketWrapper by deploying a MarketWrapper contract
 * that implements this interface using the logic of their Market.
 *
 * WARNING: MarketWrapper contracts should NEVER write to storage!
 * When implementing a MarketWrapper, exercise caution; a poorly implemented
 * MarketWrapper contract could permanently lose access to the NFT or user funds.
 */
interface IMarketWrapper {
    /**
     * @notice Given the auctionId, nftContract, and tokenId, check that:
     * 1. the auction ID matches the token
     * referred to by tokenId + nftContract
     * 2. the auctionId refers to an *ACTIVE* auction
     * (e.g. an auction that will accept bids)
     * within this market contract
     * 3. any additional validation to ensure that
     * a PartyBid can bid on this auction
     * (ex: if the market allows arbitrary bidding currencies,
     * check that the auction currency is ETH)
     * Note: This function probably should have been named "isValidAuction"
     * @dev Called in PartyBid.sol in `initialize` at line 174
     * @return TRUE if the auction is valid
     */
    function auctionIdMatchesToken(
        uint256 auctionId,
        address nftContract,
        uint256 tokenId
    ) external view returns (bool);

    /**
     * @notice Calculate the minimum next bid for this auction.
     * PartyBid contracts always submit the minimum possible
     * bid that will be accepted by the Market contract.
     * usually, this is either the reserve price (if there are no bids)
     * or a certain percentage increase above the current highest bid
     * @dev Called in PartyBid.sol in `bid` at line 251
     * @return minimum bid amount
     */
    function getMinimumBid(uint256 auctionId) external view returns (uint256);

    /**
     * @notice Query the current highest bidder for this auction
     * It is assumed that there is always 1 winning highest bidder for an auction
     * This is used to ensure that PartyBid cannot outbid itself if it is already winning
     * @dev Called in PartyBid.sol in `bid` at line 241
     * @return highest bidder
     */
    function getCurrentHighestBidder(uint256 auctionId) external view returns (address);

    /**
     * @notice Submit bid to Market contract
     * @dev Called in PartyBid.sol in `bid` at line 259
     */
    function bid(uint256 auctionId, uint256 bidAmount) external;

    /**
     * @notice Determine whether the auction has been finalized
     * Used to check if it is still possible to bid
     * And to determine whether the PartyBid should finalize the auction
     * @dev Called in PartyBid.sol in `bid` at line 247
     * @dev and in `finalize` at line 288
     * @return TRUE if the auction has been finalized
     */
    function isFinalized(uint256 auctionId) external view returns (bool);

    /**
     * @notice Finalize the results of the auction
     * on the Market contract
     * It is assumed  that this operation is performed once for each auction,
     * that after it is done the auction is over and the NFT has been
     * transferred to the auction winner.
     * @dev Called in PartyBid.sol in `finalize` at line 289
     */
    function finalize(uint256 auctionId) external;
}
"},"contracts/market-wrapper/KoansMarketWrapper.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

// ============ External Imports ============
import { IKoansAuctionHouse } from "../vendor/markets/IKoansAuctionHouse.sol";

// ============ Internal Imports ============
import { IMarketWrapper } from "./IMarketWrapper.sol";

/**
 * @title KoansMarketWrapper
 * @author Koans Founders + Anna Carroll + Nounders
 * @notice MarketWrapper contract implementing IMarketWrapper interface
 * according to the logic of Koans' Auction House, a fork of Nouns' Auction
 * House
 */
contract KoansMarketWrapper is IMarketWrapper {
    // ============ Public Immutables ============

    IKoansAuctionHouse public immutable market;

    // ======== Constructor =========

    constructor(address _koansAuctionHouse) {
        market = IKoansAuctionHouse(_koansAuctionHouse);
    }

    // ======== External Functions =========

    /**
     * @notice Determine whether there is an existing, active auction
     * for this token. In the Koans auction house, the current auction
     * id is the token id, which increments sequentially, forever. The
     * auction is considered active while the current block timestamp
     * is less than the auction's end time.
     * @return TRUE if the auction exists
     */
    function auctionExists(uint256 auctionId) public view returns (bool) {
        (uint256 currentAuctionId, , , uint256 endTime, , , ) = market.auction();
        return auctionId == currentAuctionId && block.timestamp < endTime;
    }

    /**
     * @notice Determine whether the given auctionId and tokenId is active.
     * We ignore nftContract since it is static for all koans auctions.
     * @return TRUE if the auctionId and tokenId matches the active auction
     */
    function auctionIdMatchesToken(
        uint256 auctionId,
        address /* nftContract */,
        uint256 tokenId
    ) public view override returns (bool) {
        return auctionId == tokenId && auctionExists(auctionId);
    }

    /**
     * @notice Calculate the minimum next bid for the active auction
     * @return minimum bid amount
     */
    function getMinimumBid(uint256 auctionId) external view override returns (uint256) {
        require(auctionExists(auctionId), "KoansMarketWrapper::getMinimumBid: Auction not active");

        (, uint256 amount, , , address payable bidder, , ) = market.auction();
        if (bidder == address(0)) {
            // if there are NO bids, the minimum bid is the reserve price
            return market.reservePrice();
        }
        // if there ARE bids, the minimum bid is the current bid plus the increment buffer
        uint8 minBidIncrementPercentage = market.minBidIncrementPercentage();
        return amount + ((amount * minBidIncrementPercentage) / 100);
    }

    /**
     * @notice Query the current highest bidder for this auction
     * @return highest bidder
     */
    function getCurrentHighestBidder(uint256 auctionId) external view override returns (address) {
        require(
            auctionExists(auctionId),
            "KoansMarketWrapper::getCurrentHighestBidder: Auction not active"
        );

        (, , , , address payable bidder, , ) = market.auction();
        return bidder;
    }

    /**
     * @notice Submit bid to Market contract
     */
    function bid(uint256 auctionId, uint256 bidAmount) external override {
        // line 104 of Koans Auction House, createBid() function
        (bool success, bytes memory returnData) = address(market).call{ value: bidAmount }(
            abi.encodeWithSignature("createBid(uint256)", auctionId)
        );
        require(success, string(returnData));
    }

    /**
     * @notice Determine whether the auction has been finalized
     * @return TRUE if the auction has been finalized
     */
    function isFinalized(uint256 auctionId) external view override returns (bool) {
        (uint256 currentAuctionId, , , , , bool settled, ) = market.auction();
        bool settledNormally = auctionId != currentAuctionId;
        bool settledWhenPaused = auctionId == currentAuctionId && settled;
        return settledNormally || settledWhenPaused;
    }

    /**
     * @notice Finalize the results of the auction
     */
    function finalize(uint256 /* auctionId */) external override {
        if (market.paused()) {
            market.settleAuction();
        } else {
            market.settleCurrentAndCreateNewAuction();
        }
    }
}
"},"contracts/market-wrapper/NounsMarketWrapper.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

// ============ External Imports ============
import { INounsAuctionHouse } from "../vendor/markets/INounsAuctionHouse.sol";

// ============ Internal Imports ============
import { IMarketWrapper } from "./IMarketWrapper.sol";

/**
 * @title NounsMarketWrapper
 * @author Anna Carroll + Nounders
 * @notice MarketWrapper contract implementing IMarketWrapper interface
 * according to the logic of Nouns' Auction Houses
 */
contract NounsMarketWrapper is IMarketWrapper {
    // ============ Public Immutables ============

    INounsAuctionHouse public immutable market;

    // ======== Constructor =========

    constructor(address _nounsAuctionHouse) {
        market = INounsAuctionHouse(_nounsAuctionHouse);
    }

    // ======== External Functions =========

    /**
     * @notice Determine whether there is an existing, active auction
     * for this token. In the Nouns auction house, the current auction
     * id is the token id, which increments sequentially, forever. The
     * auction is considered active while the current block timestamp
     * is less than the auction's end time.
     * @return TRUE if the auction exists
     */
    function auctionExists(uint256 auctionId) public view returns (bool) {
        (uint256 currentAuctionId, , , uint256 endTime, , ) = market.auction();
        return auctionId == currentAuctionId && block.timestamp < endTime;
    }

    /**
     * @notice Determine whether the given auctionId and tokenId is active.
     * We ignore nftContract since it is static for all nouns auctions.
     * @return TRUE if the auctionId and tokenId matches the active auction
     */
    function auctionIdMatchesToken(
        uint256 auctionId,
        address /* nftContract */,
        uint256 tokenId
    ) public view override returns (bool) {
        return auctionId == tokenId && auctionExists(auctionId);
    }

    /**
     * @notice Calculate the minimum next bid for the active auction
     * @return minimum bid amount
     */
    function getMinimumBid(uint256 auctionId) external view override returns (uint256) {
        require(auctionExists(auctionId), "NounsMarketWrapper::getMinimumBid: Auction not active");

        (, uint256 amount, , , address payable bidder, ) = market.auction();
        if (bidder == address(0)) {
            // if there are NO bids, the minimum bid is the reserve price
            return market.reservePrice();
        }
        // if there ARE bids, the minimum bid is the current bid plus the increment buffer
        uint8 minBidIncrementPercentage = market.minBidIncrementPercentage();
        return amount + ((amount * minBidIncrementPercentage) / 100);
    }

    /**
     * @notice Query the current highest bidder for this auction
     * @return highest bidder
     */
    function getCurrentHighestBidder(uint256 auctionId) external view override returns (address) {
        require(
            auctionExists(auctionId),
            "NounsMarketWrapper::getCurrentHighestBidder: Auction not active"
        );

        (, , , , address payable bidder, ) = market.auction();
        return bidder;
    }

    /**
     * @notice Submit bid to Market contract
     */
    function bid(uint256 auctionId, uint256 bidAmount) external override {
        // line 104 of Nouns Auction House, createBid() function
        (bool success, bytes memory returnData) = address(market).call{ value: bidAmount }(
            abi.encodeWithSignature("createBid(uint256)", auctionId)
        );
        require(success, string(returnData));
    }

    /**
     * @notice Determine whether the auction has been finalized
     * @return TRUE if the auction has been finalized
     */
    function isFinalized(uint256 auctionId) external view override returns (bool) {
        (uint256 currentAuctionId, , , , , bool settled) = market.auction();
        bool settledNormally = auctionId != currentAuctionId;
        bool settledWhenPaused = auctionId == currentAuctionId && settled;
        return settledNormally || settledWhenPaused;
    }

    /**
     * @notice Finalize the results of the auction
     */
    function finalize(uint256 /* auctionId */) external override {
        if (market.paused()) {
            market.settleAuction();
        } else {
            market.settleCurrentAndCreateNewAuction();
        }
    }
}
"},"contracts/market-wrapper/ZoraMarketWrapper.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

// ============ External Imports ============
import { IZoraAuctionHouse } from "../vendor/markets/IZoraAuctionHouse.sol";

// ============ Internal Imports ============
import { IMarketWrapper } from "./IMarketWrapper.sol";
import "../tokens/IERC721.sol";
import "../tokens/IERC20.sol";

/**
 * @title ZoraMarketWrapper
 * @author Anna Carroll
 * @notice MarketWrapper contract implementing IMarketWrapper interface
 * according to the logic of Zora's Auction Houses
 * Original Zora Auction House code: https://github.com/ourzora/auction-house/blob/main/contracts/AuctionHouse.sol
 */
contract ZoraMarketWrapper is IMarketWrapper {
    // ============ Internal Immutables ============

    IZoraAuctionHouse internal immutable market;
    uint8 internal immutable minBidIncrementPercentage;

    // ======== Constructor =========

    constructor(address _zoraAuctionHouse) {
        market = IZoraAuctionHouse(_zoraAuctionHouse);
        minBidIncrementPercentage = IZoraAuctionHouse(_zoraAuctionHouse)
            .minBidIncrementPercentage();
    }

    // ======== External Functions =========

    /**
     * @notice Determine whether there is an existing auction
     * for this token on the market
     * @return TRUE if the auction exists
     */
    function auctionExists(uint256 auctionId) public view returns (bool) {
        // line 375 of Zora Auction House, _exists() function (not exposed publicly)
        IZoraAuctionHouse.Auction memory _auction = market.auctions(auctionId);
        return _auction.tokenOwner != address(0);
    }

    /**
     * @notice Determine whether the given auctionId is
     * an auction for the tokenId + nftContract
     * @return TRUE if the auctionId matches the tokenId + nftContract
     */
    function auctionIdMatchesToken(
        uint256 auctionId,
        address nftContract,
        uint256 tokenId
    ) public view override returns (bool) {
        IZoraAuctionHouse.Auction memory _auction = market.auctions(auctionId);
        return
            _auction.tokenId == tokenId &&
            _auction.tokenContract == IERC721(nftContract) &&
            _auction.auctionCurrency == IERC20(address(0));
    }

    /**
     * @notice Calculate the minimum next bid for this auction
     * @return minimum bid amount
     */
    function getMinimumBid(uint256 auctionId) external view override returns (uint256) {
        // line 173 of Zora Auction House, calculation within createBid() function (calculation not exposed publicly)
        IZoraAuctionHouse.Auction memory _auction = market.auctions(auctionId);
        if (_auction.bidder == address(0)) {
            // if there are NO bids, the minimum bid is the reserve price
            return _auction.reservePrice;
        } else {
            // if there ARE bids, the minimum bid is the current bid plus the increment buffer
            return _auction.amount + ((_auction.amount * minBidIncrementPercentage) / 100);
        }
    }

    /**
     * @notice Query the current highest bidder for this auction
     * @return highest bidder
     */
    function getCurrentHighestBidder(uint256 auctionId) external view override returns (address) {
        // line 279 of NFTMarketReserveAuction, getMinBidAmount() function
        IZoraAuctionHouse.Auction memory _auction = market.auctions(auctionId);
        return _auction.bidder;
    }

    /**
     * @notice Submit bid to Market contract
     */
    function bid(uint256 auctionId, uint256 bidAmount) external override {
        // line 153 of Zora Auction House, createBid() function
        (bool success, bytes memory returnData) = address(market).call{ value: bidAmount }(
            abi.encodeWithSignature("createBid(uint256,uint256)", auctionId, bidAmount)
        );
        require(success, string(returnData));
    }

    /**
     * @notice Determine whether the auction has been finalized
     * @return TRUE if the auction has been finalized
     */
    function isFinalized(uint256 auctionId) external view override returns (bool) {
        // line 302 of Zora Auction House,
        // the auction is deleted at the end of the endAuction() function
        // since we checked that the auction DID exist when we deployed the partyBid,
        // if it no longer exists that means the auction has been finalized.
        return !auctionExists(auctionId);
    }

    /**
     * @notice Finalize the results of the auction
     */
    function finalize(uint256 auctionId) external override {
        // line 249 of Zora Auction House, endAuction() function
        market.endAuction(auctionId);
    }
}
"},"contracts/operators/CollectionBatchBuyOperator.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.20;

import "./IOperator.sol";
import "../party/Party.sol";
import "../tokens/IERC721.sol";
import "../utils/LibRawResult.sol";
import "../utils/LibAddress.sol";
import "../utils/LibSafeERC721.sol";
import "openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

/// @notice A crowdfund that purchases a specific NFT (i.e., with a known token
///         ID) listing for a known price.
contract CollectionBatchBuyOperator is IOperator {
    using LibRawResult for bytes;
    using LibSafeERC721 for IERC721;
    using LibAddress for address payable;

    struct CollectionBatchBuyOperationData {
        /// The contract of NFTs to buy.
        IERC721 nftContract;
        /// The merkle root of the token IDs that can be bought. If null,
        /// allow any token ID in the collection can be bought.
        bytes32 nftTokenIdsMerkleRoot;
        // Maximum amount this crowdfund will pay for an NFT.
        uint256 maximumPrice;
        // Minimum number of tokens that must be purchased. If this limit is
        // not reached, the batch buy will fail.
        uint256 minTokensBought;
        // Minimum amount of ETH that must be used to buy the tokens. If this
        // amount is not reached, the batch buy will fail.
        uint256 minTotalEthUsed;
    }

    struct TokenToBuy {
        // The token ID of the NFT to buy.
        uint256 tokenId;
        // The price of the token. This cannot be greater than `maximumPrice`.
        uint96 price;
        // The proof needed to verify that the token ID is included in the
        // `nftTokenIdsMerkleRoot` (if it is not null).
        bytes32[] proof;
    }

    struct BuyCall {
        // The contract to call to buy the NFTs in `tokensToBuy`.
        address payable target;
        // The calldata to call `target` with to buy the NFTs in `tokensToBuy`.
        bytes data;
        // The tokens to try buying with this call.
        TokenToBuy[] tokensToBuy;
    }

    struct CollectionBatchBuyExecutionData {
        // The calls made to buy the NFTs. Each call has a target, data, and
        // the tokens to buy in that call.
        BuyCall[] calls;
        // The total number of tokens that can be bought in this batch buy. This
        // should be equal to the sum of the each `tokensToBuy` in `calls`.
        uint256 numOfTokens;
    }

    event CollectionBatchBuyOperationExecuted(
        Party party,
        IERC721 token,
        uint256[] tokenIdsBought,
        uint256 totalEthUsed
    );

    error NothingBoughtError();
    error InvalidMinTokensBoughtError(uint256 minTokensBought);
    error InvalidTokenIdError();
    error NotEnoughTokensBoughtError(uint256 tokensBought, uint256 minTokensBought);
    error NotEnoughEthUsedError(uint256 ethUsed, uint256 minTotalEthUsed);
    error MaximumPriceError(uint256 callValue, uint256 maximumPrice);
    error CallProhibitedError(address target, bytes data);
    error NumOfTokensCannotBeLessThanMin(uint256 numOfTokens, uint256 min);
    error EthUsedForFailedBuyError(uint256 expectedEthUsed, uint256 actualEthUsed);

    function execute(
        bytes memory operatorData,
        bytes memory executionData,
        address executor,
        bool allowOperatorsToSpendPartyEth
    ) external payable {
        // Decode the operator data.
        CollectionBatchBuyOperationData memory op = abi.decode(
            operatorData,
            (CollectionBatchBuyOperationData)
        );

        // Decode the execution data.
        CollectionBatchBuyExecutionData memory ex = abi.decode(
            executionData,
            (CollectionBatchBuyExecutionData)
        );

        if (op.minTokensBought == 0) {
            // Must buy at least one token.
            revert InvalidMinTokensBoughtError(0);
        }

        if (ex.numOfTokens < op.minTokensBought) {
            // The number of tokens to buy must be greater than or equal to the
            // minimum number of tokens to buy.
            revert NumOfTokensCannotBeLessThanMin(ex.numOfTokens, op.minTokensBought);
        }

        // Lengths of arrays are updated at the end.
        uint256[] memory tokenIds = new uint256[](ex.numOfTokens);

        uint96 totalEthUsed;
        uint256 tokensBought;
        for (uint256 i; i < ex.calls.length; ++i) {
            BuyCall memory call = ex.calls[i];

            uint96 callValue;
            for (uint256 j; j < call.tokensToBuy.length; ++j) {
                TokenToBuy memory tokenToBuy = call.tokensToBuy[j];

                if (op.nftTokenIdsMerkleRoot != bytes32(0)) {
                    // Verify the token ID is in the merkle tree.
                    _verifyTokenId(tokenToBuy.tokenId, op.nftTokenIdsMerkleRoot, tokenToBuy.proof);
                }

                // Check that the call value is under the maximum price.
                uint96 price = tokenToBuy.price;
                if (price > op.maximumPrice) {
                    revert MaximumPriceError(price, op.maximumPrice);
                }

                // Add the price to the total value used for the call.
                callValue += price;
            }

            uint256 balanceBefore = address(this).balance;
            {
                // Execute the call to buy the NFT.
                (bool success, ) = _buy(call.target, callValue, call.data);

                if (!success) continue;
            }

            {
                uint96 ethUsed;
                for (uint256 j; j < call.tokensToBuy.length; ++j) {
                    uint256 tokenId = call.tokensToBuy[j].tokenId;
                    uint96 price = call.tokensToBuy[j].price;

                    // Check whether the NFT was successfully bought.
                    if (op.nftContract.safeOwnerOf(tokenId) == address(this)) {
                        ethUsed += price;
                        ++tokensBought;

                        // Add the token to the list of tokens to finalize.
                        tokenIds[tokensBought - 1] = tokenId;
                    }
                }

                // Check ETH spent for call is what was expected.
                uint256 actualEthUsed = balanceBefore - address(this).balance;
                if (ethUsed != actualEthUsed) {
                    revert EthUsedForFailedBuyError(ethUsed, actualEthUsed);
                }

                totalEthUsed += ethUsed;
            }
        }

        // This is to prevent this crowdfund from finalizing a loss if nothing
        // was attempted to be bought (ie. `tokenIds` is empty) or all NFTs were
        // bought for free.
        if (totalEthUsed == 0) revert NothingBoughtError();

        // Check number of tokens bought is not less than the minimum.
        if (tokensBought < op.minTokensBought) {
            revert NotEnoughTokensBoughtError(tokensBought, op.minTokensBought);
        }

        // Check total ETH used is not less than the minimum.
        if (totalEthUsed < op.minTotalEthUsed) {
            revert NotEnoughEthUsedError(totalEthUsed, op.minTotalEthUsed);
        }

        assembly {
            // Update length of `tokenIds`
            mstore(tokenIds, tokensBought)
        }

        // Transfer the NFTs to the party.
        for (uint256 i; i < tokenIds.length; ++i) {
            op.nftContract.safeTransferFrom(address(this), msg.sender, tokenIds[i]);
        }

        uint256 unusedEth = msg.value - totalEthUsed;
        if (unusedEth > 0) {
            if (allowOperatorsToSpendPartyEth) {
                // Transfer unused ETH to the party.
                payable(msg.sender).transferEth(unusedEth);
            } else {
                // Transfer unused ETH to the executor.
                payable(executor).transferEth(unusedEth);
            }
        }

        emit CollectionBatchBuyOperationExecuted(
            Party(payable(msg.sender)),
            op.nftContract,
            tokenIds,
            totalEthUsed
        );
    }

    function _buy(
        address payable callTarget,
        uint96 callValue,
        bytes memory callData
    ) private returns (bool success, bytes memory revertData) {
        // Check that call is not re-entering.
        if (callTarget == address(this)) {
            revert CallProhibitedError(callTarget, callData);
        }
        // Execute the call to buy the NFT.
        (success, revertData) = callTarget.call{ value: callValue }(callData);
    }

    function _verifyTokenId(uint256 tokenId, bytes32 root, bytes32[] memory proof) private pure {
        bytes32 leaf;
        assembly {
            mstore(0x00, tokenId)
            leaf := keccak256(0x00, 0x20)
        }

        if (!MerkleProof.verify(proof, root, leaf)) revert InvalidTokenIdError();
    }
}
"},"contracts/operators/IOperator.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.20;

/// @notice Performs operations on behalf of parties.
interface IOperator {
    /// @notice Executes an operation.
    /// @param operatorData Data to be used by the operator, known at the time
    ///                     operation was proposed.
    /// @param executionData Data to be used by the execution, known at the time
    ///                      operation was executed.
    /// @param executor The address that executed the operation.
    /// @param allowOperatorsToSpendPartyEth Whether operators are allowed to
    ///                                      spend party's ETH balance.
    function execute(
        bytes memory operatorData,
        bytes memory executionData,
        address executor,
        bool allowOperatorsToSpendPartyEth
    ) external payable;
}
"},"contracts/party/IPartyFactory.sol":{"content":"// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.20;

import "../globals/IGlobals.sol";
import "../tokens/IERC721.sol";

import "./Party.sol";

// Creates generic Party instances.
interface IPartyFactory {
    event PartyCreated(
        Party indexed party,
        Party.PartyOptions opts,
        IERC721[] preciousTokens,
        uint256[] preciousTokenIds,
        address creator
    );

    /// @notice Deploy a new party instance.
    /// @param partyImpl The implementation of the party to deploy.
    /// @param authorities The addresses set as authorities for the party.
    /// @param opts Options used to initialize the party. These are fixed
    ///             and cannot be changed later.
    /// @param preciousTokens The tokens that are considered precious by the
    ///                       party.These are protected assets and are subject
    ///                       to extra restrictions in proposals vs other
    ///                       assets.
    /// @param preciousTokenIds The IDs associated with each token in `preciousTokens`.
    /// @param rageQuitTimestamp The timestamp until which ragequit is enabled.
    /// @return party The newly created `Party` instance.
    function createParty(
        Party partyImpl,
        address[] memory authorities,
        Party.PartyOptions calldata opts,
        IERC721[] memory preciousTokens,
        uint256[] memory preciousTokenIds,
        uint40 rageQuitTimestamp
    ) external returns (Party party);
}
