contract TestUtils is Test {
    uint256 private immutable _nonce;

    constructor() {
        _nonce = uint256(
            keccak256(
                abi.encode(
                    tx.origin,
                    tx.origin.balance,
                    block.number,
                    block.timestamp,
                    block.coinbase
                )
            )
        );
    }

    modifier skipped() {
        return;
        _;
    }

    modifier onlyForked() {
        if (block.number < 1e6) {
            return;
        }
        _;
    }

    function _randomBytes32() internal view returns (bytes32) {
        bytes memory seed = abi.encode(_nonce, block.timestamp, gasleft());
        return keccak256(seed);
    }

    function _randomUint256() internal view returns (uint256) {
        return uint256(_randomBytes32());
    }

    function _randomAddress() internal view returns (address payable) {
        return payable(address(uint160(_randomUint256())));
    }

    function _randomRange(uint256 lo, uint256 hi) internal view returns (uint256) {
        return lo + (_randomUint256() % (hi - lo));
    }

    function _toAddressArray(address v) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = v;
    }

    function _toERC721Array(IERC721 v) internal pure returns (IERC721[] memory arr) {
        address[] memory arr_ = _toAddressArray(address(v));
        assembly {
            arr := arr_
        }
    }

    function _toUint256Array(uint256 v) internal pure returns (uint256[] memory arr) {
        arr = new uint256[](1);
        arr[0] = v;
    }

    function _expectNonIndexedEmit() internal {
        vm.expectEmit(false, false, false, true);
    }

    function _expectEmit0() internal {
        vm.expectEmit(false, false, false, true);
    }

    function _expectEmit1() internal {
        vm.expectEmit(true, false, false, true);
    }

    function _expectEmit2() internal {
        vm.expectEmit(true, true, false, true);
    }

    function _expectEmit3() internal {
        vm.expectEmit(true, true, true, true);
    }
}
"},"sol-tests/UnlockedWallet.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

contract UnlockedWallet {
    function execCall(
        address payable target,
        uint256 value,
        bytes memory data
    ) external returns (bytes memory r) {
        bool s;
        (s, r) = target.call{ value: value }(data);
        if (!s) {
            assembly {
                revert(add(r, 0x20), mload(r))
            }
        }
    }

    receive() external payable {}
}
"},"sol-tests/crowdfund/AuctionCrowdfund.t.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8;

import "forge-std/Test.sol";

import "../../contracts/crowdfund/AuctionCrowdfund.sol";
import "../../contracts/globals/Globals.sol";
import "../../contracts/globals/LibGlobals.sol";
import "../../contracts/utils/Proxy.sol";
import "../../contracts/gatekeepers/AllowListGateKeeper.sol";
import "../../contracts/renderers/RendererStorage.sol";

import "../DummyERC721.sol";
import "../TestUtils.sol";

import "./MockPartyFactory.sol";
import "./MockParty.sol";
import "./MockMarketWrapper.sol";

contract AuctionCrowdfundTest is Test, TestUtils {
    event MockPartyFactoryCreateParty(
        address caller,
        address[] authorities,
        Party.PartyOptions opts,
        IERC721[] preciousTokens,
        uint256[] preciousTokenIds
    );

    event MockMint(address caller, address owner, uint256 amount, address delegate);

    event MockMarketWrapperBid(address bidder, uint256 auctionId, uint256 bidAmount);

    event MockMarketWrapperFinalize(address caller, address winner, uint256 topBid);

    event Burned(address contributor, uint256 ethUsed, uint256 ethOwed, uint256 votingPower);
    event Contributed(
        address sender,
        address contributor,
        uint256 amount,
        address delegate,
        uint256 previousTotalContributions
    );
    event Won(uint256 bid, Party party);
    event Lost();

    string defaultName = "AuctionCrowdfund";
    string defaultSymbol = "PBID";
    uint40 defaultDuration = 60 * 60;
    uint96 defaultMaxBid = 10e18;
    address payable defaultSplitRecipient = payable(0);
    uint16 defaultSplitBps = 0.1e4;
    address defaultInitialDelegate;
    IGateKeeper defaultGateKeeper;
    bytes12 defaultGateKeeperId;

    Crowdfund.FixedGovernanceOpts governanceOpts;
    ProposalStorage.ProposalEngineOpts proposalEngineOpts;

    Globals globals = new Globals(address(this));
    MockPartyFactory partyFactory = new MockPartyFactory();
    MockMarketWrapper market = new MockMarketWrapper();
    DummyERC721 tokenToBuy;
    AuctionCrowdfund auctionCrowdfundImpl;
    MockParty party;

    constructor() {
        globals.setAddress(
            LibGlobals.GLOBAL_RENDERER_STORAGE,
            address(new RendererStorage(address(this)))
        );
        tokenToBuy = market.nftContract();
        party = partyFactory.mockParty();
        auctionCrowdfundImpl = new AuctionCrowdfund(globals);

        governanceOpts.partyFactory = partyFactory;
        governanceOpts.partyImpl = Party(payable(address(party)));
    }

    function _createCrowdfund(
        uint256 auctionId,
        uint256 tokenId,
        uint96 initialContribution,
        bool onlyHostCanBid,
        IGateKeeper gateKeeper,
        bytes12 gateKeeperId,
        address[] memory hosts
    ) private returns (AuctionCrowdfund cf) {
        governanceOpts.hosts = hosts;
        cf = AuctionCrowdfund(
            payable(
                address(
                    new Proxy{ value: initialContribution }(
                        auctionCrowdfundImpl,
                        abi.encodeCall(
                            AuctionCrowdfund.initialize,
                            AuctionCrowdfundBase.AuctionCrowdfundOptions({
                                name: defaultName,
                                symbol: defaultSymbol,
                                customizationPresetId: 0,
                                auctionId: auctionId,
                                market: market,
                                nftContract: tokenToBuy,
                                nftTokenId: tokenId,
                                duration: defaultDuration,
                                maximumBid: defaultMaxBid,
                                splitRecipient: defaultSplitRecipient,
                                splitBps: defaultSplitBps,
                                initialContributor: address(this),
                                initialDelegate: defaultInitialDelegate,
                                minContribution: 0,
                                maxContribution: type(uint96).max,
                                gateKeeper: gateKeeper,
                                gateKeeperId: gateKeeperId,
                                onlyHostCanBid: onlyHostCanBid,
                                governanceOpts: governanceOpts,
                                proposalEngineOpts: proposalEngineOpts
                            })
                        )
                    )
                )
            )
        );
    }

    function _createCrowdfund(
        uint256 auctionId,
        uint256 tokenId,
        uint96 initialContribution
    ) private returns (AuctionCrowdfund cf) {
        return
            _createCrowdfund(
                auctionId,
                tokenId,
                initialContribution,
                false,
                defaultGateKeeper,
                defaultGateKeeperId,
                governanceOpts.hosts
            );
    }

    function _createExpectedPartyOptions(
        uint256 finalPrice
    ) private view returns (Party.PartyOptions memory opts) {
        ProposalStorage.ProposalEngineOpts memory proposalEngineOpts;
        return
            Party.PartyOptions({
                name: defaultName,
                symbol: defaultSymbol,
                customizationPresetId: 0,
                governance: PartyGovernance.GovernanceOpts({
                    hosts: governanceOpts.hosts,
                    voteDuration: governanceOpts.voteDuration,
                    executionDelay: governanceOpts.executionDelay,
                    passThresholdBps: governanceOpts.passThresholdBps,
                    totalVotingPower: uint96(finalPrice),
                    feeBps: governanceOpts.feeBps,
                    feeRecipient: governanceOpts.feeRecipient
                }),
                proposalEngine: proposalEngineOpts
            });
    }

    function test_happyPath() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        address delegate = _randomAddress();
        _contribute(cf, contributor, delegate, 1e18);
        // Bid on the auction.
        _expectEmit0();
        emit MockMarketWrapperBid(address(cf), auctionId, 1337);
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // End the auction.
        market.endAuction(auctionId);
        // Finalize the crowdfund.
        _expectEmit0();
        emit MockMarketWrapperFinalize(address(cf), address(cf), 1337);
        _expectEmit0();
        emit MockPartyFactoryCreateParty(
            address(cf),
            _toAddressArray(address(cf)),
            _createExpectedPartyOptions(1337),
            _toERC721Array(tokenToBuy),
            _toUint256Array(tokenId)
        );
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(party));
        // Burn contributor's NFT, mock minting governance tokens and returning
        // unused contribution.
        _expectEmit0();
        emit MockMint(address(cf), contributor, 1337, delegate);
        _expectEmit0();
        emit Burned(contributor, 1337, 1e18 - 1337, 1337);
        cf.burn(contributor);
        assertEq(contributor.balance, 1e18 - 1337);
    }

    function test_canBidWithCustomAmountAsHost() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(
            auctionId,
            tokenId,
            0,
            false,
            IGateKeeper(address(0)),
            "",
            _toAddressArray(address(this))
        );
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        address delegate = _randomAddress();
        _contribute(cf, contributor, delegate, 1e18);
        // Expect revert if not host.
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        vm.prank(_randomAddress());
        cf.bid(1e18, governanceOpts, proposalEngineOpts, 0);
        // Bid on the auction with a custom amount as host.
        cf.bid(1e18, governanceOpts, proposalEngineOpts, 0);
    }

    function test_cannotReinitialize() external {
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        vm.expectRevert(abi.encodeWithSelector(Implementation.OnlyConstructorError.selector));
        AuctionCrowdfundBase.AuctionCrowdfundOptions memory opts;
        cf.initialize(opts);
    }

    function test_canRefundIfCrowdfundLosesAndNoBidsMade() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        market.endAuction(auctionId);
        // Expire and finalize the crowdfund.
        skip(defaultDuration);
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(0));
        // Burn contributor's NFT, which should refund all contributed ETH.
        _expectEmit0();
        emit Burned(contributor, 0, 1e18, 0);
        cf.burn(contributor);
        assertEq(contributor.balance, 1e18);
    }

    function test_canRefundIfCrowdfundLosesWithBidsMade_notFinalized() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // Outbid externally so we're losing.
        _outbidExternally(auctionId);
        // End the auction.
        market.endAuction(auctionId);
        // Expire and finalize the crowdfund.
        skip(defaultDuration);
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(0));
        // Burn contributor's NFT, which should refund all contributed ETH.
        _expectEmit0();
        emit Burned(contributor, 0, 1e18, 0);
        cf.burn(contributor);
        assertEq(contributor.balance, 1e18);
    }

    function test_canRefundIfCrowdfundLosesWithBidsMade_finalized() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // Outbid externally so we're losing.
        _outbidExternally(auctionId);
        // End the auction and finalize it.
        market.endAuction(auctionId);
        market.finalize(auctionId);
        // Expire and finalize the crowdfund.
        skip(defaultDuration);
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(0));
        // Burn contributor's NFT, which should refund all contributed ETH.
        _expectEmit0();
        emit Burned(contributor, 0, 1e18, 0);
        cf.burn(contributor);
        assertEq(contributor.balance, 1e18);
    }

    function test_canWinEvenIfExpiredIfAlsoTopBidder() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // Expire and finalize the crowdfund.
        skip(defaultDuration);
        assertEq(uint8(cf.getCrowdfundLifecycle()), uint8(Crowdfund.CrowdfundLifecycle.Expired));
        // End the auction.
        market.endAuction(auctionId);
        // Finalize the crowdfund.
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(party));
        // Burn contributor's NFT, which should refund unused ETH and mint voting power.
        _expectEmit0();
        emit Burned(contributor, 1337, 1e18 - 1337, 1337);
        cf.burn(contributor);
        assertEq(contributor.balance, 1e18 - 1337);
    }

    function test_cannotBidAfterFinalize() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // End the auction.
        market.endAuction(auctionId);
        // Finalize the crowdfund.
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(party));
        // Try to bid with the crowdfund again.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Won
            )
        );
        cf.bid(governanceOpts, proposalEngineOpts, 0);
    }

    function test_cannotFinalizeTwice() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // End the auction.
        market.endAuction(auctionId);
        // Finalize the crowdfund.
        Party party_ = cf.finalize(governanceOpts, proposalEngineOpts);
        assertEq(address(party_), address(party));
        // Try to finalize the crowdfund again.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Won
            )
        );
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_cannotFinalizeTooEarlyWithNoBids() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Finalize the crowdfund early.
        vm.expectRevert("AUCTION_NOT_ENDED");
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_canFinalizeIfExpiredBeforeAuctionEnds_noBids() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        market.endAuction(auctionId);
        // Finalize the crowdfund.
        _expectEmit0();
        emit Lost();
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_canFinalizeIfExpiredAfterAuctionEnds_noBids() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        skip(defaultDuration);
        market.endAuction(auctionId);
        _expectEmit0();
        emit Lost();
        // Finalize the crowdfund.
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_canFinalizeIfExpiredAndAuctionFinalized_noBids() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        skip(defaultDuration);
        market.endAuction(auctionId);
        market.finalize(auctionId);
        _expectEmit0();
        emit Lost();
        // Finalize the crowdfund.
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_cannotFinalizeIfExpiredBeforeAuctionEndsIfHighestBidder() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Place a bid.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // Expire the CF.
        skip(defaultDuration);
        // Check that the CF is highest bidder.
        assertTrue(market.getCurrentHighestBidder(auctionId) == address(cf));
        // Check that the CF is expired.
        assertTrue(cf.getCrowdfundLifecycle() == Crowdfund.CrowdfundLifecycle.Expired);
        // Finalize the crowdfund.
        vm.expectRevert("AUCTION_NOT_ENDED");
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_canFinalizeIfExpiredBeforeAuctionEndsIfNotHighestBidder() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Place a bid.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // Get outbid.
        _outbidExternally(auctionId);
        // Expire the CF.
        skip(defaultDuration);
        // Check that the CF is not highest bidder.
        assertTrue(market.getCurrentHighestBidder(auctionId) != address(cf));
        // Check that the CF is expired.
        assertTrue(cf.getCrowdfundLifecycle() == Crowdfund.CrowdfundLifecycle.Expired);
        // Finalize the crowdfund.
        cf.finalize(governanceOpts, proposalEngineOpts);
        assertTrue(cf.getCrowdfundLifecycle() == Crowdfund.CrowdfundLifecycle.Lost);
    }

    function test_canFinalizeIfExpiredAfterAuctionEnds_withBids() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        uint256 bid = market.getMinimumBid(auctionId);
        // Place a bid.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // Expire the CF.
        skip(defaultDuration);
        // End the auction.
        market.endAuction(auctionId);
        _expectEmit0();
        emit Won(bid, Party(payable(address(party))));
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_canFinalizeIfExpiredAndNeverBid() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        market.getMinimumBid(auctionId);
        // Expire the CF.
        skip(defaultDuration);
        _expectEmit0();
        emit Lost();
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_cannotReenterFinalize() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // End the auction.
        market.endAuction(auctionId);
        // Set up a callback to reenter finalize().
        market.setCallback(
            address(cf),
            abi.encodeCall(cf.finalize, (governanceOpts, proposalEngineOpts)),
            0
        );
        // Finalize the crowdfund.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Busy
            )
        );
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_cannotReenterBid() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Set up a callback to reenter bid().
        market.setCallback(address(cf), abi.encodeWithSignature("bid()"), 0);
        // Bid on the auction.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Busy
            )
        );
        cf.bid(governanceOpts, proposalEngineOpts, 0);
    }

    function test_cannotReenterContributeThroughBid() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Set up a callback to reenter bid().
        market.setCallback(address(cf), abi.encodeCall(cf.contribute, (contributor, "")), 1);
        // Bid on the auction.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Busy
            )
        );
        cf.bid(governanceOpts, proposalEngineOpts, 0);
    }

    function test_cannotReenterContributeThroughFinalize() external {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Bid on the auction.
        cf.bid(governanceOpts, proposalEngineOpts, 0);
        // End the auction.
        market.endAuction(auctionId);
        // Set up a callback to reenter contribute().
        market.setCallback(address(cf), abi.encodeCall(cf.contribute, (contributor, "")), 1);
        // Finalize the crowdfund.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Busy
            )
        );
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_onlyHostCanBid() public {
        address host = _randomAddress();
        address contributor = _randomAddress();

        // Create a AuctionCrowdfund instance with `onlyHost` enabled.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(0);
        AuctionCrowdfund cf = _createCrowdfund(
            auctionId,
            tokenId,
            0,
            true,
            IGateKeeper(address(0)),
            "",
            _toAddressArray(host)
        );

        // Contributor contributes.
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, abi.encode(new bytes32[](0)));

        // Skip past exipry.
        vm.warp(cf.expiry());

        // Bid, expect revert because we are not a host.
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        cf.bid(governanceOpts, proposalEngineOpts, 0);

        // Bid as a contributor, but expect a revert because they are not a host.
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        vm.prank(contributor);
        cf.bid(governanceOpts, proposalEngineOpts, 0);

        // Bid as the host, but expect a revert because the CF is expired.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Expired
            )
        );
        vm.prank(host);
        cf.bid(governanceOpts, proposalEngineOpts, 0);
    }

    function test_onlyHostCanBidWithGatekeeperSet() public {
        address host = _randomAddress();
        address contributor = _randomAddress();

        // Create a AuctionCrowdfund instance with onlyHostCanBid and gatekeeper enabled.
        AllowListGateKeeper gateKeeper = new AllowListGateKeeper();
        bytes32 contributorHash = keccak256(abi.encodePacked(contributor));
        bytes12 gateKeeperId = gateKeeper.createGate(contributorHash);
        (uint256 auctionId, uint256 tokenId) = market.createAuction(0);
        AuctionCrowdfund cf = _createCrowdfund(
            auctionId,
            tokenId,
            0,
            true,
            gateKeeper,
            gateKeeperId,
            _toAddressArray(host)
        );

        // Contributor contributes.
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, abi.encode(new bytes32[](0)));

        // Skip past exipry.
        vm.warp(cf.expiry());

        // Bid, expect revert because we are not a host or contributor.
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        cf.bid(governanceOpts, proposalEngineOpts, 0);

        // Bid as a contributor, but expect a revert because onlyHost is on.
        vm.expectRevert(abi.encodeWithSelector(Crowdfund.OnlyPartyHostError.selector));
        vm.prank(contributor);
        cf.bid(governanceOpts, proposalEngineOpts, 0);

        // Bid as the host, but expect a revert because the CF is expired.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Expired
            )
        );
        vm.prank(host);
        cf.bid(governanceOpts, proposalEngineOpts, 0);
    }

    function test_onlyContributorCanBid() public {
        address host = _randomAddress();
        address contributor = _randomAddress();

        // Create a AuctionCrowdfund instance with a gatekeeper enabled.
        AllowListGateKeeper gateKeeper = new AllowListGateKeeper();
        bytes32 contributorHash = keccak256(abi.encodePacked(contributor));
        bytes12 gateKeeperId = gateKeeper.createGate(contributorHash);
        (uint256 auctionId, uint256 tokenId) = market.createAuction(0);
        AuctionCrowdfund cf = _createCrowdfund(
            auctionId,
            tokenId,
            0,
            false,
            gateKeeper,
            gateKeeperId,
            _toAddressArray(host)
        );

        // Contributor contributes.
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, abi.encode(new bytes32[](0)));

        // Skip past expiry.
        vm.warp(cf.expiry());

        // Bid, expect revert because we are not a contributor.
        vm.expectRevert(Crowdfund.OnlyContributorError.selector);
        cf.bid(governanceOpts, proposalEngineOpts, 0);

        // Bid as a contributor, but expect a revert because the CF is expired.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                Crowdfund.CrowdfundLifecycle.Expired
            )
        );
        vm.prank(contributor);
        cf.bid(governanceOpts, proposalEngineOpts, 0);

        // Bid as the host, but expect a revert because the host is not a contributor.
        vm.expectRevert(Crowdfund.OnlyContributorError.selector);
        vm.prank(host);
        cf.bid(governanceOpts, proposalEngineOpts, 0);
    }

    function test_gettingNFTForFreeTriggersLostToRefund() public {
        // Create a token and auction with min bid of 1337 wei.
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        // Create a AuctionCrowdfund instance.
        AuctionCrowdfund cf = _createCrowdfund(auctionId, tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        _contribute(cf, contributor, 1e18);
        // Acquire the NFT to gift.
        _outbidExternally(auctionId);
        skip(defaultDuration);
        market.endAuction(auctionId);
        market.finalize(auctionId);
        // Gift the NFT to the crowdfund.
        IERC721 token = IERC721(market.nftContract());
        address winner = token.ownerOf(tokenId);
        vm.prank(winner);
        token.transferFrom(winner, address(cf), tokenId);
        assertEq(token.ownerOf(tokenId), address(cf));
        // Finalize the crowdfund.
        _expectEmit0();
        emit Lost();
        cf.finalize(governanceOpts, proposalEngineOpts);
    }

    function test_creation_initialContribution() external {
        (uint256 auctionId, uint256 tokenId) = market.createAuction(1337);
        uint256 initialContribution = _randomRange(1, 1 ether);
        address initialContributor = _randomAddress();
        address initialDelegate = _randomAddress();
        vm.deal(address(this), initialContribution);
        emit Contributed(
            address(this),
            initialContributor,
            initialContribution,
            initialDelegate,
            0
        );
        AuctionCrowdfund(
            payable(
                address(
                    new Proxy{ value: initialContribution }(
                        auctionCrowdfundImpl,
                        abi.encodeCall(
                            AuctionCrowdfund.initialize,
                            AuctionCrowdfundBase.AuctionCrowdfundOptions({
                                name: defaultName,
                                symbol: defaultSymbol,
                                customizationPresetId: 0,
                                auctionId: auctionId,
                                market: market,
                                nftContract: tokenToBuy,
                                nftTokenId: tokenId,
                                duration: defaultDuration,
                                maximumBid: defaultMaxBid,
                                splitRecipient: defaultSplitRecipient,
                                splitBps: defaultSplitBps,
                                initialContributor: initialContributor,
                                initialDelegate: initialDelegate,
                                minContribution: 0,
                                maxContribution: type(uint96).max,
                                gateKeeper: defaultGateKeeper,
                                gateKeeperId: defaultGateKeeperId,
                                onlyHostCanBid: false,
                                governanceOpts: governanceOpts,
                                proposalEngineOpts: proposalEngineOpts
                            })
                        )
                    )
                )
            )
        );
    }

    function _contribute(AuctionCrowdfund cf, address contributor, uint256 amount) private {
        vm.deal(contributor, amount);
        vm.prank(contributor);
        cf.contribute{ value: amount }(contributor, "");
    }

    function _contribute(
        AuctionCrowdfund cf,
        address contributor,
        address delegate,
        uint256 amount
    ) private {
        uint256 previousTotalContributions = cf.totalContributions();
        _expectEmit0();
        emit Contributed(contributor, contributor, amount, delegate, previousTotalContributions);
        vm.deal(contributor, amount);
        vm.prank(contributor);
        cf.contribute{ value: amount }(delegate, "");
    }

    function _outbidExternally(uint256 auctionId) private {
        market.bid{ value: market.getMinimumBid(auctionId) }(auctionId, _randomAddress());
    }
}
"},"sol-tests/crowdfund/BuyCrowdfund.t.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8;

import "forge-std/Test.sol";

import "../../contracts/crowdfund/BuyCrowdfund.sol";
import "../../contracts/globals/Globals.sol";
import "../../contracts/globals/LibGlobals.sol";
import "../../contracts/utils/Proxy.sol";
import "../../contracts/gatekeepers/AllowListGateKeeper.sol";
import "../../contracts/renderers/RendererStorage.sol";

import "../DummyERC721.sol";
import "../TestUtils.sol";

import "./MockPartyFactory.sol";
import "./TestERC721Vault.sol";

contract BuyCrowdfundTest is Test, TestUtils {
    event MockPartyFactoryCreateParty(
        address caller,
        address[] authorities,
        Party.PartyOptions opts,
        IERC721[] preciousTokens,
        uint256[] preciousTokenIds
    );

    event MockMint(address caller, address owner, uint256 amount, address delegate);

    event Contributed(
        address sender,
        address contributor,
        uint256 amount,
        address delegate,
        uint256 previousTotalContributions
    );
    event DelegateUpdated(
        address sender,
        address contributor,
        address oldDelegate,
        address newDelegate
    );
    event Lost();

    string defaultName = "BuyCrowdfund";
    string defaultSymbol = "PBID";
    uint40 defaultDuration = 60 * 60;
    uint96 defaultMaxPrice = 10e18;
    address payable defaultSplitRecipient = payable(0);
    uint16 defaultSplitBps = 0.1e4;
    address defaultInitialDelegate;
    IGateKeeper defaultGateKeeper;
    bytes12 defaultGateKeeperId;
    Crowdfund.FixedGovernanceOpts govOpts;
    ProposalStorage.ProposalEngineOpts proposalEngineOpts;

    Globals globals = new Globals(address(this));
    MockPartyFactory partyFactory = new MockPartyFactory();
    TestERC721Vault erc721Vault = new TestERC721Vault();
    BuyCrowdfund buyCrowdfundImpl;
    MockParty party;

    constructor() {
        globals.setAddress(
            LibGlobals.GLOBAL_RENDERER_STORAGE,
            address(new RendererStorage(address(this)))
        );
        party = partyFactory.mockParty();
        buyCrowdfundImpl = new BuyCrowdfund(globals);

        govOpts.partyImpl = Party(payable(address(party)));
        govOpts.partyFactory = partyFactory;
    }

    function setUp() public {}

    function _createCrowdfund(
        uint256 tokenId,
        uint96 initialContribution,
        bool onlyHostCanBuy,
        IGateKeeper gateKeeper,
        bytes12 gateKeeperId,
        address[] memory hosts
    ) private returns (BuyCrowdfund cf) {
        govOpts.hosts = hosts;
        cf = BuyCrowdfund(
            payable(
                address(
                    new Proxy{ value: initialContribution }(
                        buyCrowdfundImpl,
                        abi.encodeCall(
                            BuyCrowdfund.initialize,
                            BuyCrowdfund.BuyCrowdfundOptions({
                                name: defaultName,
                                symbol: defaultSymbol,
                                customizationPresetId: 0,
                                nftContract: erc721Vault.token(),
                                nftTokenId: tokenId,
                                duration: defaultDuration,
                                maximumPrice: defaultMaxPrice,
                                splitRecipient: defaultSplitRecipient,
                                splitBps: defaultSplitBps,
                                initialContributor: address(this),
                                initialDelegate: defaultInitialDelegate,
                                minContribution: 0,
                                maxContribution: type(uint96).max,
                                gateKeeper: gateKeeper,
                                gateKeeperId: gateKeeperId,
                                onlyHostCanBuy: onlyHostCanBuy,
                                governanceOpts: govOpts,
                                proposalEngineOpts: proposalEngineOpts
                            })
                        )
                    )
                )
            )
        );
    }

    function _createCrowdfund(
        uint256 tokenId,
        uint96 initialContribution
    ) private returns (BuyCrowdfund cf) {
        return
            _createCrowdfund(
                tokenId,
                initialContribution,
                false,
                defaultGateKeeper,
                defaultGateKeeperId,
                govOpts.hosts
            );
    }

    function _createExpectedPartyOptions(
        uint256 finalPrice
    ) private view returns (Party.PartyOptions memory opts) {
        ProposalStorage.ProposalEngineOpts memory proposalEngineOpts;
        return
            Party.PartyOptions({
                name: defaultName,
                symbol: defaultSymbol,
                customizationPresetId: 0,
                governance: PartyGovernance.GovernanceOpts({
                    hosts: govOpts.hosts,
                    voteDuration: govOpts.voteDuration,
                    executionDelay: govOpts.executionDelay,
                    passThresholdBps: govOpts.passThresholdBps,
                    totalVotingPower: uint96(finalPrice),
                    feeBps: govOpts.feeBps,
                    feeRecipient: govOpts.feeRecipient
                }),
                proposalEngine: proposalEngineOpts
            });
    }

    function testHappyPath() public {
        uint256 tokenId = erc721Vault.mint();
        // Create a BuyCrowdfund instance.
        BuyCrowdfund cf = _createCrowdfund(tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        address delegate = _randomAddress();
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(delegate, "");
        // Buy the token.
        vm.expectEmit(false, false, false, true);
        emit MockPartyFactoryCreateParty(
            address(cf),
            _toAddressArray(address(cf)),
            _createExpectedPartyOptions(0.5e18),
            _toERC721Array(erc721Vault.token()),
            _toUint256Array(tokenId)
        );
        Party party_ = cf.buy(
            payable(address(erc721Vault)),
            0.5e18,
            abi.encodeCall(erc721Vault.claim, (tokenId)),
            govOpts,
            proposalEngineOpts,
            0
        );
        assertEq(address(party), address(party_));
        // Burn contributor's NFT, mock minting governance tokens and returning
        // unused contribution.
        vm.expectEmit(false, false, false, true);
        emit MockMint(address(cf), contributor, 0.5e18, delegate);
        cf.burn(contributor);
        assertEq(contributor.balance, 0.5e18);
    }

    // The call to buy() does not transfer the token.
    function testBuyDoesNotTransferToken() public {
        uint256 tokenId = erc721Vault.mint();
        // Create a BuyCrowdfund instance.
        BuyCrowdfund cf = _createCrowdfund(tokenId, 0);
        // Contribute and delegate.
        address payable contributor = _randomAddress();
        address delegate = _randomAddress();
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(delegate, "");
        // Pretend to buy the token.
        vm.expectRevert(
            abi.encodeWithSelector(
                BuyCrowdfundBase.FailedToBuyNFTError.selector,
                erc721Vault.token(),
                tokenId
            )
        );
        cf.buy(
            _randomAddress(), // Call random EOA, which will succeed but do nothing
            0.5e18,
            "",
            govOpts,
            proposalEngineOpts,
            0
        );
        assertTrue(cf.getCrowdfundLifecycle() == Crowdfund.CrowdfundLifecycle.Active);
    }

    function testOnlyHostCanBuy() public {
        // Create a BuyCrowdfund instance with `onlyHost` enabled.
        address host = _randomAddress();
        address contributor = _randomAddress();

        BuyCrowdfund cf = _createCrowdfund(
            0,
            0,
            true,
            IGateKeeper(address(0)),
            0,
            _toAddressArray(host)
        );

        assertEq(cf.onlyHostCanBuy(), true);

        // Contributor contributes.
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, abi.encode(new bytes32[](0)));

        // Buy the token and expect revert because we are not a host.
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        cf.buy(payable(address(0)), 0, "", govOpts, proposalEngineOpts, 0);

        // Now as the host, but this will fail with another error because
        // we are trying to call the CF itself in buy().
        vm.prank(host);
        vm.expectRevert(
            abi.encodeWithSelector(BuyCrowdfundBase.CallProhibitedError.selector, address(cf), "")
        );
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);

        // Buy as a contributor, but this will fail because only the host can
        // call buy().
        vm.prank(contributor);
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);
    }

    function testOnlyHostCanBuy_CannotFakeGovernanceOpts() public {
        // Create a BuyCrowdfund instance with `onlyHost` enabled.
        address host = _randomAddress();

        BuyCrowdfund cf = _createCrowdfund(
            0,
            0,
            true,
            IGateKeeper(address(0)),
            0,
            _toAddressArray(host)
        );

        // Buy as the host, but pass in wrong governanceOpts.
        vm.prank(host);
        vm.expectRevert(Crowdfund.InvalidGovernanceOptionsError.selector);
        govOpts.voteDuration += 1;
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);
    }

    function testOnlyContributorCanBuy() public {
        address host = _randomAddress();
        address contributor = _randomAddress();

        // Create a BuyCrowdfund instance with a gatekeeper enabled.
        AllowListGateKeeper gateKeeper = new AllowListGateKeeper();
        bytes32 contributorHash = keccak256(abi.encodePacked(contributor));
        bytes12 gateKeeperId = gateKeeper.createGate(contributorHash);
        BuyCrowdfund cf = _createCrowdfund(
            0,
            0,
            false,
            gateKeeper,
            gateKeeperId,
            _toAddressArray(host)
        );

        // Contributor contributes.
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, abi.encode(new bytes32[](0)));

        // Buy the token, expect revert because we are not a contributor or host.
        vm.expectRevert(Crowdfund.OnlyContributorError.selector);
        cf.buy(payable(address(0)), 0, "", govOpts, proposalEngineOpts, 0);

        // Now as the host, but this will fail because the host is not a contributor.
        vm.prank(host);
        vm.expectRevert(Crowdfund.OnlyContributorError.selector);
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);

        // Buy as a contributor, but this will fail with another error because
        // we are trying to call the CF itself in buy().
        vm.prank(contributor);
        vm.expectRevert(
            abi.encodeWithSelector(BuyCrowdfundBase.CallProhibitedError.selector, address(cf), "")
        );
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);
    }

    function testOnlyHostOrCanBuy_withGatekeeperSet() public {
        address host = _randomAddress();
        address contributor = _randomAddress();

        // Create a BuyCrowdfund instance with onlyHostCanBuy and a gatekeeper enabled.
        AllowListGateKeeper gateKeeper = new AllowListGateKeeper();
        bytes32 contributorHash = keccak256(abi.encodePacked(contributor));
        bytes12 gateKeeperId = gateKeeper.createGate(contributorHash);
        BuyCrowdfund cf = _createCrowdfund(
            0,
            0,
            true,
            gateKeeper,
            gateKeeperId,
            _toAddressArray(host)
        );

        // Contributor contributes.
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, abi.encode(new bytes32[](0)));

        // Buy the token, expect revert because we are not a contributor or host.
        vm.expectRevert(Crowdfund.OnlyPartyHostError.selector);
        cf.buy(payable(address(0)), 0, "", govOpts, proposalEngineOpts, 0);

        // Now as the host, but this will fail with another error because
        // we are trying to call the CF itself in buy().
        vm.prank(host);
        vm.expectRevert(
            abi.encodeWithSelector(BuyCrowdfundBase.CallProhibitedError.selector, address(cf), "")
        );
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);

        // Buy as a contributor, but this will fail because onlyHost is on.
        vm.prank(contributor);
        vm.expectRevert(abi.encodeWithSelector(Crowdfund.OnlyPartyHostError.selector));
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);
    }

    function testOnlyHostOrContributorCanBuy_CannotFakeGovernanceOpts() public {
        // Create a BuyCrowdfund instance with `onlyHost` enabled.
        address host = _randomAddress();

        // Create a BuyCrowdfund instance with onlyHostCanBuy and a gatekeeper enabled.
        AllowListGateKeeper gateKeeper = new AllowListGateKeeper();
        bytes12 gateKeeperId = gateKeeper.createGate(0);
        BuyCrowdfund cf = _createCrowdfund(
            0,
            0,
            true,
            gateKeeper,
            gateKeeperId,
            _toAddressArray(host)
        );

        // Buy as the host, but pass in wrong governanceOpts.
        vm.prank(host);
        vm.expectRevert(Crowdfund.InvalidGovernanceOptionsError.selector);
        govOpts.voteDuration += 1;
        cf.buy(payable(address(cf)), 0, "", govOpts, proposalEngineOpts, 0);
    }

    function testBuyCannotExceedTotalContributions() public {
        uint256 tokenId = erc721Vault.mint();
        // Create a BuyCrowdfund instance.
        BuyCrowdfund cf = _createCrowdfund(tokenId, 0);
        // Contribute.
        address payable contributor = _randomAddress();
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, "");
        // Transfer ETH to the crowdfund (not through contribution).
        uint96 totalContributions = cf.totalContributions();
        vm.deal(address(cf), totalContributions + 1);
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.ExceedsTotalContributionsError.selector,
                totalContributions + 1,
                totalContributions
            )
        );
        cf.buy(
            payable(address(erc721Vault)),
            totalContributions + 1,
            abi.encodeCall(erc721Vault.claim, (tokenId)),
            govOpts,
            proposalEngineOpts,
            0
        );
    }

    function testBuyCannotReenter() public {
        uint256 tokenId = erc721Vault.mint();
        // Create a BuyCrowdfund instance.
        BuyCrowdfund cf = _createCrowdfund(tokenId, 0);
        // Contribute.
        address payable contributor = _randomAddress();
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, "");
        bytes memory callData = abi.encodeCall(cf.contribute, (contributor, ""));
        // Attempt reentering back into the crowdfund directly.
        vm.expectRevert(
            abi.encodeWithSelector(
                BuyCrowdfundBase.CallProhibitedError.selector,
                address(cf),
                callData
            )
        );
        cf.buy(payable(address(cf)), 1e18, callData, govOpts, proposalEngineOpts, 0);
        ReenteringContract reenteringContract = new ReenteringContract();
        // Attempt reentering back into the crowdfund via a proxy.
        vm.expectRevert(
            abi.encodeWithSelector(
                Crowdfund.WrongLifecycleError.selector,
                uint8(Crowdfund.CrowdfundLifecycle.Busy)
            )
        );
        cf.buy(
            payable(address(reenteringContract)),
            1e18,
            abi.encodeCall(reenteringContract.reenter, (cf)),
            govOpts,
            proposalEngineOpts,
            0
        );
        assertTrue(cf.getCrowdfundLifecycle() == Crowdfund.CrowdfundLifecycle.Active);
    }

    function testBuyCannotApprove() public {
        uint256 tokenId = erc721Vault.mint();
        // Create a BuyCrowdfund instance.
        BuyCrowdfund cf = _createCrowdfund(tokenId, 0);
        // Contribute.
        address payable contributor = _randomAddress();
        vm.deal(contributor, 1e18);
        vm.prank(contributor);
        cf.contribute{ value: contributor.balance }(contributor, "");
        // Attempt calling `approve()`.
        bytes memory callData = abi.encodeCall(IERC721.approve, (contributor, tokenId));
        vm.expectRevert(
            abi.encodeWithSelector(
                BuyCrowdfundBase.CallProhibitedError.selector,
                address(cf),
                callData
            )
        );
        cf.buy(payable(address(cf)), 1e18, callData, govOpts, proposalEngineOpts, 0);
        // Attempt calling `setApprovalForAll()`.
        callData = abi.encodeCall(IERC721.setApprovalForAll, (contributor, true));
        IERC721 token = erc721Vault.token();
        vm.expectRevert(
            abi.encodeWithSelector(
                BuyCrowdfundBase.CallProhibitedError.selector,
                address(token),
                callData
            )
        );
        cf.buy(payable(address(token)), 1e18, callData, govOpts, proposalEngineOpts, 0);
    }

    function testGettingNFTForFreeTriggersLostToRefund() public {
        DummyERC721 token = erc721Vault.token();
        uint256 tokenId = erc721Vault.mint();
        // Create a BuyCrowdfund instance.
        BuyCrowdfund cf = _createCrowdfund(tokenId, 0);
        // Acquire NFT for free.
        vm.prank(address(cf));
        erc721Vault.claim(tokenId);
        _expectEmit0();
        emit Lost();
        cf.buy(
            payable(address(token)),
            0,
            abi.encodeCall(token.mint, (address(cf))),
            govOpts,
            proposalEngineOpts,
            0
        );
        assertTrue(cf.getCrowdfundLifecycle() == Crowdfund.CrowdfundLifecycle.Lost);
    }

    function testCannotReinitialize() public {
        uint256 tokenId = erc721Vault.mint();
