                proposalEngine: proposalEngineOpts
            }),
            expectedTokens,
            expectedTokenIds
        );
        // Buy the tokens.
        cf.batchBuy(
            CollectionBatchBuyCrowdfund.BatchBuyArgs({
                tokenIds: tokenIds,
                callTargets: callTargets,
                callValues: callValues,
                callDatas: callDatas,
                proofs: proofs,
                minTokensBought: tokenIds.length - 1,
                minTotalEthUsed: 0,
                governanceOpts: govOpts,
                proposalEngineOpts: proposalEngineOpts,
                hostIndex: 0
            })
        );
