        _truncate(calls[0].data, 1);
        IProposalExecutionEngine.ExecuteProposalParams memory prop = _createTestProposal(calls);
        vm.expectRevert(
            abi.encodeWithSelector(
                ArbitraryCallsProposal.InvalidApprovalCallLength.selector,
