    // Test a proposal where the zora listing expires and the
    // OS listing also expires.
    function testForked_Execution_AllExpiring() public onlyForked {
        address buyer = _randomAddress();
        uint256 listPrice = 1e18;
        uint40 listDuration = 7 days;
        (IERC721 token, uint256 tokenId) = _randomPreciousToken();
        (, IProposalExecutionEngine.ExecuteProposalParams memory executeParams) = _createProposal(
            token,
            tokenId,
            listPrice,
            listDuration,
            new uint256[](0),
            new address payable[](0)
        );
        // This will list on zora because the proposal was not passed unanimously.
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        // Timeeout the zora listing.
        skip(ZORA_AUCTION_TIMEOUT);
        // Next, retrieve from zora and list on OS.
        uint256 listStartTime = block.timestamp;
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionExpired(_getNextZoraAuctionId() - 1, block.timestamp);
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        bytes32 orderHash;
        uint256 expiry;
        {
            (, orderHash, , expiry) = abi.decode(
                executeParams.progressData,
                (ListOnOpenseaAdvancedProposal.ListOnOpenseaStep, bytes32, address, uint256)
            );
        }
        // Skip past expiration.
        skip(listDuration);
        // Attempt to buy the listing (fail).
        vm.expectRevert(
            abi.encodeWithSelector(IOpenseaExchange.InvalidTime.selector, listStartTime, expiry)
        );
        _buyOpenseaListing(
            BuyOpenseaListingParams({
                maker: payable(impl),
                buyer: buyer,
                tokenType: ListOnOpenseaAdvancedProposal.TokenType.ERC721,
                token: address(token),
                tokenId: tokenId,
                listPrice: listPrice,
                startTime: listStartTime,
                duration: listDuration,
                zone: address(0),
                conduitKey: SEAPORT_CONDUIT_KEY
            })
        );
        // Finalize the listing.
        vm.expectEmit(false, false, false, true);
        emit OpenseaOrderExpired(orderHash, address(token), tokenId, expiry);
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        assertEq(executeParams.progressData.length, 0);
        // We should still own the NFT.
        assertEq(token.ownerOf(tokenId), address(impl));
        // Seaport should not have an allowance.
        assertEq(token.getApproved(tokenId), address(0));
    }

    // Test a proposal where the zora listing is bought.
    function testForked_Execution_BoughtOnZora() public onlyForked {
        address buyer = _randomAddress();
        uint256 listPrice = 1e18;
        uint40 listDuration = 7 days;
        (IERC721 token, uint256 tokenId) = _randomPreciousToken();
        (, IProposalExecutionEngine.ExecuteProposalParams memory executeParams) = _createProposal(
            token,
            tokenId,
            listPrice,
            listDuration,
            new uint256[](0),
            new address payable[](0)
        );
        // This will list on zora because the proposal was not passed unanimously.
        uint256 auctionId = _getNextZoraAuctionId();
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionCreated(
            auctionId,
            token,
            tokenId,
            listPrice,
            uint40(ZORA_AUCTION_DURATION),
            uint40(block.timestamp) + uint40(ZORA_AUCTION_TIMEOUT)
        );
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        {
            (, ZoraHelpers.ZoraProgressData memory progressData) = abi.decode(
                executeParams.progressData,
                (ListOnOpenseaAdvancedProposal.ListOnOpenseaStep, ZoraHelpers.ZoraProgressData)
            );
            assertEq(progressData.auctionId, auctionId);
        }
        // Try to advance the proposal before the zora auction has timed out (fail).
        skip(ZORA_AUCTION_TIMEOUT - 1);
        vm.expectRevert(
            abi.encodeWithSelector(
                ListOnZoraProposal.ZoraListingNotExpired.selector,
                auctionId,
                block.timestamp + 1
            )
        );
        impl.executeListOnOpensea(executeParams);

        // Bid on the zora auction.
        _bidOnZoraListing(auctionId, buyer, listPrice);
        // The auction will be now extended by ZORA_AUCTION_DURATION.

        // Try to advance the proposal before the zora auction has ended (fail).
        skip(ZORA_AUCTION_DURATION - 1);
        vm.expectRevert("Auction hasn't completed");
        impl.executeListOnOpensea(executeParams);

        // Skip past the end of the auction.
        skip(1);
        // Advance the proposal, finalizing the zora auction.
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionSold(auctionId);
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        assertEq(executeParams.progressData.length, 0);
        // Buyer should own the NFT.
        assertEq(token.ownerOf(tokenId), buyer);
        // Proposal contract should have the bid price.
        assertEq(address(impl).balance, LIST_PRICE);
    }

    // Test a proposal where the zora listing is cancelled.
    function testForked_Execution_BoughtOnZora_Cancelled() public onlyForked {
        // Zroa will cancel the auction during settlement because the buyer cannot receive the NFT.
        address buyer = address(this);
        uint256 listPrice = 1e18;
        uint40 listDuration = 7 days;
        (IERC721 token, uint256 tokenId) = _randomPreciousToken();
        (, IProposalExecutionEngine.ExecuteProposalParams memory executeParams) = _createProposal(
            token,
            tokenId,
            listPrice,
            listDuration,
            new uint256[](0),
            new address payable[](0)
        );
        // This will list on zora because the proposal was not passed unanimously.
        uint256 auctionId = _getNextZoraAuctionId();
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionCreated(
            auctionId,
            token,
            tokenId,
            listPrice,
            uint40(ZORA_AUCTION_DURATION),
            uint40(block.timestamp) + uint40(ZORA_AUCTION_TIMEOUT)
        );
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        {
            (, ZoraHelpers.ZoraProgressData memory progressData) = abi.decode(
                executeParams.progressData,
                (ListOnOpenseaAdvancedProposal.ListOnOpenseaStep, ZoraHelpers.ZoraProgressData)
            );
            assertEq(progressData.auctionId, auctionId);
        }
        // Try to advance the proposal before the zora auction has timed out (fail).
        skip(ZORA_AUCTION_TIMEOUT - 1);
        vm.expectRevert(
            abi.encodeWithSelector(
                ListOnZoraProposal.ZoraListingNotExpired.selector,
                auctionId,
                block.timestamp + 1
            )
        );
        impl.executeListOnOpensea(executeParams);

        // Bid on the zora auction.
        _bidOnZoraListing(auctionId, buyer, listPrice);
        // The auction will be now extended by ZORA_AUCTION_DURATION.

        // Skip past the end of the auction.
        skip(ZORA_AUCTION_DURATION);
        // Advance the proposal, finalizing the zora auction.
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionFailed(auctionId);
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        // Listing cancelled because the buyer could not receive the NFT. The
        // proposal should be done.
        assertEq(executeParams.progressData.length, 0);
    }

    // Test a proposal where the zora listing is bought and finalized externally.
    function testForked_Execution_BoughtOnZora_settledExternally() public onlyForked {
        address buyer = _randomAddress();
        uint256 listPrice = 1e18;
        uint40 listDuration = 7 days;
        (IERC721 token, uint256 tokenId) = _randomPreciousToken();
        (, IProposalExecutionEngine.ExecuteProposalParams memory executeParams) = _createProposal(
            token,
            tokenId,
            listPrice,
            listDuration,
            new uint256[](0),
            new address payable[](0)
        );
        // This will list on zora because the proposal was not passed unanimously.
        uint256 auctionId = _getNextZoraAuctionId();
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionCreated(
            auctionId,
            token,
            tokenId,
            listPrice,
            uint40(ZORA_AUCTION_DURATION),
            uint40(block.timestamp) + uint40(ZORA_AUCTION_TIMEOUT)
        );
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        {
            (, ZoraHelpers.ZoraProgressData memory progressData) = abi.decode(
                executeParams.progressData,
                (ListOnOpenseaAdvancedProposal.ListOnOpenseaStep, ZoraHelpers.ZoraProgressData)
            );
            assertEq(progressData.auctionId, auctionId);
        }
        // Bid on the zora auction.
        _bidOnZoraListing(auctionId, buyer, listPrice);
        // The auction will be now extended by ZORA_AUCTION_DURATION.
        // Skip past the end of the auction.
        skip(ZORA_AUCTION_DURATION);
        // Settle externally.
        ZORA.endAuction(auctionId);

        // Advance the proposal, finalizing the zora auction.
        vm.expectEmit(false, false, false, true);
        emit ZoraAuctionSold(auctionId);
        executeParams.progressData = impl.executeListOnOpensea(executeParams);
        assertEq(executeParams.progressData.length, 0);
        // Buyer should own the NFT.
        assertEq(token.ownerOf(tokenId), buyer);
        // Proposal contract should have the bid price.
        assertEq(address(impl).balance, LIST_PRICE);
    }
}
"},"sol-tests/proposals/ListOnZoraProposalForked.t.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8;

import "contracts/proposals/ListOnZoraProposal.sol";
import "contracts/globals/Globals.sol";
import "../TestUtils.sol";
import "../DummyERC721.sol";
import "./TestableListOnZoraProposal.sol";
import "./ZoraTestUtils.sol";

contract ListOnZoraProposalForkedTest is ZoraTestUtils, TestUtils {
    IZoraAuctionHouse ZORA = IZoraAuctionHouse(0xE468cE99444174Bd3bBBEd09209577d25D1ad673);
    Globals globals = new Globals(address(this));
    TestableListOnZoraProposal proposal = new TestableListOnZoraProposal(globals, ZORA);
    DummyERC721 nftToken = new DummyERC721();
    uint256 nftTokenId;

    event ZoraAuctionCreated(
        uint256 auctionId,
        IERC721 token,
        uint256 tokenId,
        uint256 startingPrice,
        uint40 duration,
        uint40 timeoutTime
    );
    event ZoraAuctionExpired(uint256 auctionId, uint256 expiry);
    event ZoraAuctionSold(uint256 auctionId);
    event ZoraAuctionFailed(uint256 auctionId);

    // Zora events
    event AuctionCreated(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address indexed tokenContract,
        uint256 duration,
        uint256 reservePrice,
        address tokenOwner,
        address curator,
        uint8 curatorFeePercentage,
        address auctionCurrency
    );
    event AuctionBid(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address indexed tokenContract,
        address sender,
        uint256 value,
        bool firstBid,
        bool extended
    );
    event AuctionCanceled(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address indexed tokenContract,
        address tokenOwner
    );
    event AuctionEnded(
        uint256 indexed auctionId,
        uint256 indexed tokenId,
        address indexed tokenContract,
        address tokenOwner,
        address curator,
        address winner,
        uint256 amount,
        uint256 curatorFee,
        address auctionCurrency
    );

    constructor() ZoraTestUtils(ZORA) {
        nftTokenId = nftToken.mint(address(proposal));
    }

    function _createExecutionParams()
        private
        view
        returns (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        )
    {
        proposalData = ListOnZoraProposal.ZoraProposalData({
            listPrice: _randomUint256() % 1e18,
            timeout: uint40(_randomRange(1 hours, 1 days)),
            duration: uint40(_randomRange(1 hours, 1 days)),
            token: nftToken,
            tokenId: nftTokenId
        });
        executeParams.proposalData = abi.encode(proposalData);
    }

    function _bidOnListing(uint256 auctionId, uint256 bid) private {
        _bidOnListing(_randomAddress(), auctionId, bid);
    }

    function _bidOnListing(address bidder, uint256 auctionId, uint256 bid) private {
        IZoraAuctionHouse.Auction memory auction = ZORA.auctions(auctionId);
        uint256 timeBuffer = ZORA.timeBuffer();
        vm.deal(bidder, bid);
        vm.prank(bidder);
        _expectEmit3();
        emit AuctionBid(
            auctionId,
            auction.tokenId,
            address(auction.tokenContract),
            bidder,
            bid,
            auction.firstBidTime == 0,
            block.timestamp - auction.firstBidTime - auction.duration <= timeBuffer
        );
        ZORA.createBid{ value: bid }(auctionId, bid);
    }

    function testForked_canCreateListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        _expectEmit3();
        emit AuctionCreated(
            auctionId,
            proposalData.tokenId,
            address(proposalData.token),
            proposalData.duration,
            proposalData.listPrice,
            address(proposal),
            address(0),
            0,
            address(0)
        );
        _expectEmit0();
        emit ZoraAuctionCreated(
            auctionId,
            proposalData.token,
            proposalData.tokenId,
            proposalData.listPrice,
            proposalData.duration,
            uint40(block.timestamp + proposalData.timeout)
        );
        assertTrue(proposal.executeListOnZora(executeParams).length > 0);
        assertEq(proposalData.token.ownerOf(proposalData.tokenId), address(ZORA));
    }

    function testForked_canBidOnListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        proposal.executeListOnZora(executeParams);
        _bidOnListing(auctionId, proposalData.listPrice);
    }

    function testForked_canCancelExpiredListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        executeParams.progressData = proposal.executeListOnZora(executeParams);
        skip(proposalData.timeout);
        _expectEmit3();
        emit AuctionCanceled(
            auctionId,
            proposalData.tokenId,
            address(proposalData.token),
            address(proposal)
        );
        _expectEmit0();
        emit ZoraAuctionExpired(auctionId, block.timestamp);
        assertTrue(proposal.executeListOnZora(executeParams).length == 0);
    }

    function testForked_cannotCancelUnexpiredListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        executeParams.progressData = proposal.executeListOnZora(executeParams);
        skip(proposalData.timeout - 1);
        vm.expectRevert(
            abi.encodeWithSelector(
                ListOnZoraProposal.ZoraListingNotExpired.selector,
                auctionId,
                block.timestamp + 1
            )
        );
        proposal.executeListOnZora(executeParams);
    }

    function testForked_cannotSettleOngoingListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        executeParams.progressData = proposal.executeListOnZora(executeParams);
        _bidOnListing(auctionId, proposalData.listPrice);
        vm.expectRevert("Auction hasn't completed");
        proposal.executeListOnZora(executeParams);
    }

    function testForked_canSettleSuccessfulListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        executeParams.progressData = proposal.executeListOnZora(executeParams);
        _bidOnListing(auctionId, proposalData.listPrice);
        skip(proposalData.duration);
        _expectEmit0();
        emit ZoraAuctionSold(auctionId);
        assertTrue(proposal.executeListOnZora(executeParams).length == 0);
        assertEq(address(proposal).balance, proposalData.listPrice);
    }

    function testForked_canSettleSuccessfulEndedListing() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        executeParams.progressData = proposal.executeListOnZora(executeParams);
        _bidOnListing(auctionId, proposalData.listPrice);
        skip(proposalData.duration);
        ZORA.endAuction(auctionId);
        _expectEmit0();
        emit ZoraAuctionSold(auctionId);
        assertTrue(proposal.executeListOnZora(executeParams).length == 0);
        assertEq(address(proposal).balance, proposalData.listPrice);
    }

    function testForked_canSettleIfAuctionFails() external onlyForked {
        (
            IProposalExecutionEngine.ExecuteProposalParams memory executeParams,
            ListOnZoraProposal.ZoraProposalData memory proposalData
        ) = _createExecutionParams();
        uint256 auctionId = _getNextZoraAuctionId();
        executeParams.progressData = proposal.executeListOnZora(executeParams);
        // Use a bidder that reverts when it receives the NFT, failing the entire
        // auction.
        _bidOnListing(address(new BadBidder()), auctionId, proposalData.listPrice);
        skip(proposalData.duration);
        _expectEmit0();
        emit ZoraAuctionFailed(auctionId);
        assertTrue(proposal.executeListOnZora(executeParams).length == 0);
        assertEq(address(proposal).balance, 0);
        assertEq(proposalData.token.ownerOf(proposalData.tokenId), address(proposal));
    }
}

contract BadBidder {
    function onERC721Received(
        address,
        address,
        uint256,
        bytes memory
    ) external pure returns (bytes4) {
        revert("nope");
    }
}
